Step 1: R computes a summary

species_summary &lt;- penguins |&gt;
  filter(!is.na(body_mass_g), !is.na(flipper_length_mm)) |&gt;
  group_by(species) |&gt;
  summarise(
    n = n(),
    mean_body_mass_g = mean(body_mass_g),
    mean_flipper_length_mm = mean(flipper_length_mm)
  ) |&gt;
  as.data.frame()

